package com.gregtech.gregtech.client;
import com.gregtech.gregtech.registry.GTSpikes;import com.gregtech.gregtech.block.misc.SpikeBlock;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.api.distmarker.Dist;import net.neoforged.neoforge.client.event.RegisterColorHandlersEvent;
@EventBusSubscriber(modid = com.gregtech.gregtech.api.mod.GregTechIdentity.MOD_ID,bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class SpikesClientSetup {@SubscribeEvent public static void blocks(RegisterColorHandlersEvent.Block e){for(var b:GTSpikes.all())e.register((s,l,p,t)->t==0?b.get().materialTint(s.getValue(SpikeBlock.SECONDARY)):0xFFFFFF,b.get());}@SubscribeEvent public static void items(RegisterColorHandlersEvent.Item e){for(var b:GTSpikes.all())e.register((s,t)->{var data=s.get(net.minecraft.core.component.DataComponents.BLOCK_STATE);return t==0?b.get().materialTint(data!=null&&Boolean.parseBoolean(data.properties().getOrDefault("secondary","false"))):0xFFFFFF;},b.get().asItem());}}
